def lin(col_snake, logic):
    from common import pascal
    return {"A": (f"{LIN['A']}.{pascal(col_snake)}", logic), "B": (f"{LIN['B']}.{col_snake}", logic), "C": (f"{LIN['C']}.{col_snake}", logic)}


